import { useEffect, useState } from "react";
import { api } from "../api/manuscriptApi";
import { useParams, useNavigate } from "react-router-dom";
import axios from "axios";

export default function ManuscriptForm({ method }) {
  const { id } = useParams();
  const navigate = useNavigate();

  const [authors, setAuthors] = useState([]);

  const [form, setForm] = useState({
    title: "",
    abstract: "",
    keywords: "",
    reference_list: "",
    cover_letter: "",
    manuscript_file: null,
    supplementary_materials: [],
    plagiarism_score: 0,
    author_id: "",
    journal_id: "",
    assigned_editor_id: "",
    status: "Submitted",
  });

  // Fetch authors
  useEffect(() => {
    const fetchAuthors = async () => {
      try {
        const res = await axios.get("http://localhost:5000/api/users?role=Author");
        setAuthors(res.data);
      } catch (err) {
        console.error("Failed to fetch authors:", err);
      }
    };
    fetchAuthors();
  }, []);

  // Load manuscript if editing
  useEffect(() => {
    if (method === "edit") {
      api.get(`/${id}`).then((res) => {
        const m = res.data;
        setForm({
          ...m,
          keywords: m.keywords?.join(","),
          supplementary_materials: [],
        });
      });
    }
  }, [id]);

  const handleSubmit = async (e) => {
    e.preventDefault();

    const fd = new FormData();
    Object.entries(form).forEach(([k, v]) => {
      if (k === "manuscript_file" && v) {
        fd.append(k, v);
      } else if (k === "supplementary_materials" && v.length > 0) {
        Array.from(v).forEach((file) => fd.append("supplementary_materials", file));
      } else {
        fd.append(k, v);
      }
    });

    try {
      if (method === "create") await api.post("/", fd);
      else await api.put(`/${id}`, fd);
      navigate("/journal/list");
    } catch (err) {
      console.error("Error submitting manuscript:", err);
      alert("Error submitting manuscript. Check console for details.");
    }
  };

  return (
    <div className="container mt-5">
      <div className="card shadow-lg border-0 p-4">
        <h3 className="mb-4 text-primary fw-bold">
          {method === "create" ? "Create Manuscript" : "Edit Manuscript"}
        </h3>

        <form onSubmit={handleSubmit} className="row g-4">

          {/* Title */}
          <div className="col-12">
            <label className="form-label fw-semibold">Manuscript Title</label>
            <input
              className="form-control form-control-lg"
              placeholder="Enter manuscript title"
              value={form.title}
              onChange={(e) => setForm({ ...form, title: e.target.value })}
              required
            />
          </div>

          {/* Abstract */}
          <div className="col-12">
            <label className="form-label fw-semibold">Abstract</label>
            <textarea
              className="form-control"
              placeholder="Write your abstract here..."
              value={form.abstract}
              onChange={(e) => setForm({ ...form, abstract: e.target.value })}
              rows={5}
              required
            />
          </div>

          {/* Reference List */}
          <div className="col-12">
            <label className="form-label fw-semibold">Reference List</label>
            <textarea
              className="form-control"
              placeholder="Add references, one per line..."
              value={form.reference_list}
              onChange={(e) => setForm({ ...form, reference_list: e.target.value })}
              rows={4}
            />
          </div>

          {/* Cover Letter */}
          <div className="col-12">
            <label className="form-label fw-semibold">Cover Letter</label>
            <textarea
              className="form-control"
              placeholder="Add cover letter..."
              value={form.cover_letter}
              onChange={(e) => setForm({ ...form, cover_letter: e.target.value })}
              rows={3}
            />
          </div>

          {/* Keywords */}
          <div className="col-md-6">
            <label className="form-label fw-semibold">Keywords</label>
            <input
              className="form-control"
              placeholder="e.g. AI, Machine Learning, Data Science"
              value={form.keywords}
              onChange={(e) => setForm({ ...form, keywords: e.target.value })}
            />
          </div>

          {/* Plagiarism Score */}
          <div className="col-md-6">
            <label className="form-label fw-semibold">Plagiarism Score (%)</label>
            <input
              type="number"
              className="form-control"
              value={form.plagiarism_score}
              onChange={(e) =>
                setForm({ ...form, plagiarism_score: e.target.value })
              }
            />
          </div>

          {/* Author */}
          <div className="col-md-6">
            <label className="form-label fw-semibold">Select Author</label>
            <select
              className="form-control"
              value={form.author_id}
              onChange={(e) => setForm({ ...form, author_id: e.target.value })}
              required
            >
              <option value="">-- Select Author --</option>
              {authors.map((a) => (
                <option key={a.id} value={a.id}>
                  {a.name}
                </option>
              ))}
            </select>
          </div>

          {/* Journal ID */}
          <div className="col-md-6">
            <label className="form-label fw-semibold">Journal ID</label>
            <input
              type="number"
              className="form-control"
              value={form.journal_id}
              onChange={(e) =>
                setForm({ ...form, journal_id: e.target.value })
              }
            />
          </div>

          {/* Editor ID */}
          <div className="col-md-6">
            <label className="form-label fw-semibold">Assigned Editor ID</label>
            <input
              type="number"
              className="form-control"
              value={form.assigned_editor_id}
              onChange={(e) =>
                setForm({ ...form, assigned_editor_id: e.target.value })
              }
            />
          </div>

          {/* Manuscript File */}
          <div className="col-12">
            <label className="form-label fw-semibold">Upload Manuscript</label>
            <input
              type="file"
              className="form-control"
              onChange={(e) =>
                setForm({ ...form, manuscript_file: e.target.files[0] })
              }
              accept=".pdf,.doc,.docx"
              required={method === "create"}
            />
          </div>

          {/* Supplementary Files */}
          <div className="col-12">
            <label className="form-label fw-semibold">Supplementary Files</label>
            <input
              type="file"
              className="form-control"
              multiple
              onChange={(e) =>
                setForm({ ...form, supplementary_materials: e.target.files })
              }
            />
          </div>

          {/* Status */}
          <div className="col-md-6">
            <label className="form-label fw-semibold">Status</label>
            <select
              className="form-control"
              value={form.status}
              onChange={(e) => setForm({ ...form, status: e.target.value })}
            >
              <option>Submitted</option>
              <option>Under Review</option>
              <option>Revision Requested</option>
              <option>Revision Submitted</option>
              <option>Accepted</option>
              <option>Published</option>
              <option>Desk Reject</option>
            </select>
          </div>

          {/* Submit */}
          <div className="col-12 mt-4">
            <button className="btn btn-primary btn-lg w-100">
              Save Manuscript
            </button>
          </div>

        </form>
      </div>
    </div>
  );
}
